  audit:{titleLabel:"Temuan audit",descriptionLabel:"Kriteria, kondisi, sebab, dampak, dan corrective action",descriptionPlaceholder:"Kriteria audit, bukti objektif, akar masalah, dampak, pemilik tindakan, dan verifikasi penutupan.",submitLabel:"Simpan temuan audit",showAmount:false,amountLabel:"",amountHelp:"",summaryKeys:["audit_reference","standard","finding_type","owner","due_date"],fields:[{key:"audit_reference",label:"Referensi audit",type:"text",required:true},{key:"standard",label:"Kriteria / standar",type:"text",required:true,placeholder:"SOP, ISO, kontrak, regulasi yang berlaku"},{key:"finding_type",label:"Klasifikasi temuan",type:"select",required:true,options:["Observation","Minor","Major","Critical","Opportunity for improvement"]},{key:"owner",label:"Pemilik tindakan korektif",type:"text",required:true},{key:"due_date",label:"Target penyelesaian",type:"date",required:true}]},
